mod tests;
mod oracle_tests;
mod benchmarks;

use std::hash::keccakf1600;
use std::runtime::is_unconstrained;

global BLOCK_SIZE_IN_BYTES: u32 = 136; //(1600 - BITS * 2) / WORD_SIZE;
global WORD_SIZE: u32 = 8; // Limbs are made up of u64s so 8 bytes each.
global LIMBS_PER_BLOCK: u32 = BLOCK_SIZE_IN_BYTES / WORD_SIZE;
global NUM_KECCAK_LANES: u32 = 25;

#[no_predicates]
pub fn keccak256<let N: u32>(input: [u8; N], message_size: u32) -> [u8; 32] {
    assert(N >= message_size);

    // Copy input to block bytes. For that we'll need at least input bytes (N)
    // but we want it to be padded to a multiple of BLOCK_SIZE_IN_BYTES.
    let mut block_bytes = [0; ((N / BLOCK_SIZE_IN_BYTES) + 1) * BLOCK_SIZE_IN_BYTES];
    if is_unconstrained() {
        for i in 0..message_size {
            block_bytes[i] = input[i];
        }
    } else {
        for i in 0..N {
            if i < message_size {
                block_bytes[i] = input[i];
            }
        }
    }

    //1. format_input_lanes and apply padding
    let max_blocks = (N + BLOCK_SIZE_IN_BYTES) / BLOCK_SIZE_IN_BYTES;
    let real_max_blocks = (message_size + BLOCK_SIZE_IN_BYTES) / BLOCK_SIZE_IN_BYTES;

    // Apply Keccak padding (0x01 after message, 0x80 at block end)
    apply_keccak_padding(&mut block_bytes, message_size, real_max_blocks);

    // populate a vector of 64-bit limbs from our byte array
    let mut sliced_buffer =
        [0; (((N / BLOCK_SIZE_IN_BYTES) + 1) * BLOCK_SIZE_IN_BYTES) / WORD_SIZE];
    for i in 0..sliced_buffer.len() {
        let limb_start = WORD_SIZE * i;

        let mut sliced = 0;
        let mut v = 1;
        sliced += v * (block_bytes[limb_start] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 1] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 2] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 3] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 4] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 5] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 6] as Field);
        v *= 256;
        sliced += v * (block_bytes[limb_start + 7] as Field);
        sliced.assert_max_bit_size::<64>();
        sliced_buffer[i] = sliced as u64;
    }

    //2. sponge_absorb
    let mut state: [u64; NUM_KECCAK_LANES] = [0; NUM_KECCAK_LANES];
    // `real_max_blocks` is guaranteed to at least be `1`
    // We peel out the first block as to avoid a conditional inside of the loop.
    // Otherwise, a dynamic predicate can cause a blowup in a constrained runtime.
    state[0] = sliced_buffer[0];
    state[1] = sliced_buffer[1];
    state[2] = sliced_buffer[2];
    state[3] = sliced_buffer[3];
    state[4] = sliced_buffer[4];
    state[5] = sliced_buffer[5];
    state[6] = sliced_buffer[6];
    state[7] = sliced_buffer[7];
    state[8] = sliced_buffer[8];
    state[9] = sliced_buffer[9];
    state[10] = sliced_buffer[10];
    state[11] = sliced_buffer[11];
    state[12] = sliced_buffer[12];
    state[13] = sliced_buffer[13];
    state[14] = sliced_buffer[14];
    state[15] = sliced_buffer[15];
    state[16] = sliced_buffer[16];
    state = keccakf1600(state);

    let state = if is_unconstrained() {
        // When in an unconstrained runtime we can take advantage of runtime loop bounds,
        // thus allowing us to simplify the loop body.
        for i in 1..real_max_blocks {
            for j in 0..LIMBS_PER_BLOCK {
                state[j] = state[j] ^ sliced_buffer[i * LIMBS_PER_BLOCK + j];
            }
            state = keccakf1600(state);
        }

        state
    } else {
        // We store the intermediate states in an array to avoid having a dynamic predicate
        // inside the loop, which can cause a blowup in a constrained runtime.
        let mut intermediate_states = [state; (N + BLOCK_SIZE_IN_BYTES) / BLOCK_SIZE_IN_BYTES + 1];
        for i in 1..max_blocks {
            let mut previous_state = intermediate_states[i - 1];
            for j in 0..LIMBS_PER_BLOCK {
                previous_state[j] = previous_state[j] ^ sliced_buffer[i * LIMBS_PER_BLOCK + j];
            }
            intermediate_states[i] = keccakf1600(previous_state);
        }

        // We can then take the state as of `real_max_blocks`, ignoring later permutations.
        intermediate_states[real_max_blocks - 1]
    };

    //3. sponge_squeeze
    let mut result = [0; 32];
    let lane = state[0] as Field;
    let lane_le: [u8; 8] = lane.to_le_bytes();
    result[0] = lane_le[0];
    result[1] = lane_le[1];
    result[2] = lane_le[2];
    result[3] = lane_le[3];
    result[4] = lane_le[4];
    result[5] = lane_le[5];
    result[6] = lane_le[6];
    result[7] = lane_le[7];

    let lane = state[1] as Field;
    let lane_le: [u8; 8] = lane.to_le_bytes();
    result[8 * 1] = lane_le[0];
    result[8 * 1 + 1] = lane_le[1];
    result[8 * 1 + 2] = lane_le[2];
    result[8 * 1 + 3] = lane_le[3];
    result[8 * 1 + 4] = lane_le[4];
    result[8 * 1 + 5] = lane_le[5];
    result[8 * 1 + 6] = lane_le[6];
    result[8 * 1 + 7] = lane_le[7];

    let lane = state[2] as Field;
    let lane_le: [u8; 8] = lane.to_le_bytes();
    result[8 * 2] = lane_le[0];
    result[8 * 2 + 1] = lane_le[1];
    result[8 * 2 + 2] = lane_le[2];
    result[8 * 2 + 3] = lane_le[3];
    result[8 * 2 + 4] = lane_le[4];
    result[8 * 2 + 5] = lane_le[5];
    result[8 * 2 + 6] = lane_le[6];
    result[8 * 2 + 7] = lane_le[7];

    let lane = state[3] as Field;
    let lane_le: [u8; 8] = lane.to_le_bytes();
    result[8 * 3] = lane_le[0];
    result[8 * 3 + 1] = lane_le[1];
    result[8 * 3 + 2] = lane_le[2];
    result[8 * 3 + 3] = lane_le[3];
    result[8 * 3 + 4] = lane_le[4];
    result[8 * 3 + 5] = lane_le[5];
    result[8 * 3 + 6] = lane_le[6];
    result[8 * 3 + 7] = lane_le[7];

    result
}

// Apply Keccak padding to the block_bytes array
// Append 0x01 after message, then 0x80 at end of block
// If both padding bytes collide at the same byte, combine them as 0x81
#[inline_always]
pub(crate) fn apply_keccak_padding<let BLOCK_BYTES: u32>(
    block_bytes: &mut [u8; BLOCK_BYTES],
    message_size: u32,
    real_max_blocks: u32,
) {
    let real_blocks_bytes = real_max_blocks * BLOCK_SIZE_IN_BYTES;

    if message_size == real_blocks_bytes - 1 {
        // Combine both padding bits: 0x01 | 0x80 = 0x81
        block_bytes[message_size] = 0x81;
    } else {
        block_bytes[message_size] = 0x01;
        block_bytes[real_blocks_bytes - 1] = 0x80;
    }
}

67.source:
// The OPRF nullifier every wallet credential circuit publishes.
//
// WHY. A nullifier derived from the wallet address and values the verifier
// already holds (the keccak schemes these circuits used before) gives the
// wallet away: the KYC'd addresses are public on EAS, so a verifier hashes each
// one until the nullifier matches (2026-10-22: 313,955 addresses, about
// 3.5 s). Here the nullifier needs an OPRF key k that only the OPRF nodes hold,
// the nodes see the query only multiplied by a random blinding factor, and the
// circuit checks their Chaum-Pedersen proof, so nobody -- neither the nodes nor
// the verifier -- can compute it from an address.
//
// THE CONSTRUCTION (TACEO, SoW and their answers, 2026-11-17):
//
//   query     = Poseidon2(DS_QUERY, address, domain, scope)
//   A         = beta * encode_to_curve(query)           (the blinded query)
//   B         = k * A                                     (the nodes' answer)
//   P         = B / beta                                  (unblinded by the client)
//   nullifier = Poseidon2(DS_OUT, query, P.x, P.y)
//   key hash  = Poseidon2(DS_KEY, D.x, D.y),  D = k * G  (the OPRF public key)
//
// `verify_oprf_nullifier` recomputes A from beta and the query, recomputes
// B = beta * P (so the client's unblinding is checked), verifies the
// Chaum-Pedersen proof that log_G(D) = log_A(B) (DS_DLOG), and derives the
// nullifier -- oprf-nr's `verified_oprf` (TaceoLabs/oprf-nr v2.0.0) -- then
// requires the published nullifier and key hash to be those values.
//
// Poseidon2(a, b, ...) is the BN254 Poseidon2 permutation of width = number of
// inputs, output state[1] -- oprf-nr's convention. Every DS is its ASCII
// string read as a big-endian integer (each is under 31 bytes, so below p).
// `address` is the wallet's 20 bytes read big-endian. `domain` and `scope` are
// field elements; a string maps to keccak256(string) mod p before it gets
// here (the circuit cannot see the string).
//
// WHAT A VERIFIER MUST DO. Pin `oprf_key_hash` to the key registered for the
// circuit it accepts (one key per proof type: the same wallet, domain and
// scope then give unrelated nullifiers in two circuits). A proof with any other
// key hash says nothing: whoever holds a key can compute every address's
// nullifier under it. Compare `domain` and `scope` with keccak256(string) mod p
// of the strings it asked for.
//
// Mirrored off-circuit by ../scripts/oprf-nullifier (fixtures, TACEO's
// crates) and ../../proofport-oprf (the service); the tests in tests.nr pin
// this file to values those crates computed.

use babyjubjub::{BabyJubJubPoint, BabyJubJubPointInSubgroup};
use oprf::oprf_output::verified_oprf;
use poseidon2::bn254::permutation;

mod test_vectors;
mod tests;

/// b"TACEO_OPRF_zkProofport_query"
pub global DS_QUERY: Field = 8873080049130461605566892302184544221631163997938119966801040601721;
/// b"TACEO_OPRF_zkProofport_out"
pub global DS_OUT: Field = 135392456804358850182600285372688968225573181120881957501105524;
/// b"TACEO_OPRF_bjj_key"
pub global DS_KEY: Field = 7339639790271784127253828559220533810128249;
/// b"DLOG Equality Proof" -- taceo-oprf-core's DLOG_DS.
pub global DS_DLOG: Field = 1523098184080632582082867317389990410064981862;

/// The private inputs a prover gets from the OPRF nodes' answer and its own
/// blinding. None of them is public.
pub struct OprfAnswer {
    /// The OPRF public key D = k * G. Bound by its hash, which is public.
    pub public_key_x: Field,
    pub public_key_y: Field,
    /// The client's blinding factor, a BabyJubJub scalar, not zero.
    pub beta: Field,
    /// The nodes' Chaum-Pedersen proof (e in the base field, s a scalar).
    pub dlog_e: Field,
    pub dlog_s: Field,
    /// The unblinded answer P = B / beta.
    pub response_x: Field,
    pub response_y: Field,
}

/// A wallet address as the query takes it: the 20 bytes big-endian.
pub fn address_field(address: [u8; 20]) -> Field {
    let mut acc: Field = 0;
    for i in 0..20 {
        acc = acc * 256 + address[i] as Field;
    }
    acc
}

pub fn oprf_query(address: Field, domain: Field, scope: Field) -> Field {
    permutation::t4([DS_QUERY, address, domain, scope])[1]
}

pub fn key_hash(public_key: BabyJubJubPointInSubgroup) -> Field {
    permutation::t3([DS_KEY, public_key.x(), public_key.y()])[1]
}

/// The nullifier for `address` (the wallet the credential checks proved) in
/// (`domain`, `scope`), under the key whose hash is `oprf_key_hash`.
pub fn verify_oprf_nullifier(
    address: [u8; 20],
    domain: Field,
    scope: Field,
    oprf_key_hash: Field,
    nullifier: Field,
    answer: OprfAnswer,
) {
    // On the curve and in the prime-order subgroup. A pinned key hash already
    // fixes the point, so this matters only to a verifier that pins nothing --
    // and then the proof means nothing anyway; it is here so the point the
    // Chaum-Pedersen check uses is never outside the group it reasons about.
    let public_key = BabyJubJubPointInSubgroup::new(answer.public_key_x, answer.public_key_y);
    assert(key_hash(public_key) == oprf_key_hash, "OPRF key hash mismatch");

    // On the curve here; verified_oprf adds the subgroup check.
    let response = BabyJubJubPoint::new(answer.response_x, answer.response_y);
    let derived = verified_oprf(
        answer.beta,
        public_key,
        answer.dlog_e,
        answer.dlog_s,
        response,
        oprf_query(address_field(address), domain, scope),
        DS_DLOG,
        DS_OUT,
    );
    assert(derived == nullifier, "Nullifier mismatch");
}

